          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\r\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\r\n */\r\n//(1)==============================================================\r\nimport java.io.*;\r\nimport java.util.*;\r\n\r\npublic class BSTree {\r\n   Node root;\r\n   BSTree() {root=null;}\r\n   boolean isEmpty() {\r\n       return(root==null);\r\n      }\r\n   void clear() {\r\n       root=null;\r\n      }\r\n   void visit(Node p) {\r\n      System.out.print(\"p.info: \");\r\n      if(p != null) System.out.println(p.info + \" \");\r\n     }\r\n   void fvisit(Node p, RandomAccessFile f) throws Exception {\r\n      if(p != null) f.writeBytes(p.info + \" \");\r\n     }\r\n   void breadth(Node p, RandomAccessFile f) throws Exception {\r\n     if(p==null) return;\r\n     Queue q = new Queue();\r\n     q.enqueue(p);Node r;\r\n     while(!q.isEmpty()) {\r\n        r = q.dequeue();\r\n        fvisit(r,f);\r\n        if(r.left!=null) q.enqueue(r.left);\r\n        if(r.right!=null) q.enqueue(r.right);\r\n       }\r\n    }\r\n   void preOrder(Node p, RandomAccessFile f) throws Exception {\r\n      if(p==null) return;\r\n      fvisit(p,f);\r\n      preOrder(p.left,f);\r\n      preOrder(p.right,f);\r\n     }\r\n   void inOrder(Node p, RandomAccessFile f) throws Exception {\r\n      if(p==null) return;\r\n      inOrder(p.left,f);\r\n      fvisit(p,f);\r\n      inOrder(p.right,f);\r\n     }\r\n   void postOrder(Node p, RandomAccessFile f) throws Exception {\r\n      if(p==null) return;\r\n      postOrder(p.left,f);\r\n      postOrder(p.right,f);\r\n      fvisit(p,f);\r\n     }\r\n\r\n   void loadData(int k) { //do not edit this function\r\n      String [] a = Lib.readLineToStrArray(\"data.txt\", k);\r\n      int [] b = Lib.readLineToIntArray(\"data.txt\", k+1);\r\n      int [] c = Lib.readLineToIntArray(\"data.txt\", k+2);\r\n      int n = a.length;\r\n      for(int i=0;i<n;i++) insert(a[i],b[i],c[i]);\r\n     }\r\n\r\n//===========================================================================\r\n//(2)===YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\r\n//===========================================================================\r\n  void insert(String xPlace, int xPrice, int xType) {\r\n    //You should insert here statements to complete this function\r\n    if (xPlace.charAt(0) == 'A') return;\r\n    Brick b = new Brick(xPlace, xPrice, xType);\r\n    root = insertRec(root, b);\r\n   }\r\n\r\n  Node insertRec(Node node, Brick b) {\r\n    if (node == null) return new Node(b);\r\n    if (b.type < node.info.type) node.left = insertRec(node.left, b);\r\n    else if (b.type > node.info.type) node.right = insertRec(node.right, b);\r\n    return node;\r\n   }\r\n\r\n  java.util.List<Node> preOrderList(Node p) {\r\n    java.util.ArrayList<Node> result = new java.util.ArrayList<Node>();\r\n    preOrderListHelper(p, result);\r\n    return result;\r\n   }\r\n\r\n  void preOrderListHelper(Node p, java.util.ArrayList<Node> result) {\r\n    if (p == null) return;\r\n    result.add(p);\r\n    preOrderListHelper(p.left, result);\r\n    preOrderListHelper(p.right, result);\r\n   }\r\n\r\n  java.util.List<Node> inOrderList(Node p) {\r\n    java.util.ArrayList<Node> result = new java.util.ArrayList<Node>();\r\n    inOrderListHelper(p, result);\r\n    return result;\r\n   }\r\n\r\n  void inOrderListHelper(Node p, java.util.ArrayList<Node> result) {\r\n    if (p == null) return;\r\n    inOrderListHelper(p.left, result);\r\n    result.add(p);\r\n    inOrderListHelper(p.right, result);\r\n   }\r\n\r\n  Node deleteByType(Node node, int typeKey) {\r\n    if (node == null) return null;\r\n    if (typeKey < node.info.type) {\r\n      node.left = deleteByType(node.left, typeKey);\r\n    } else if (typeKey > node.info.type) {\r\n      node.right = deleteByType(node.right, typeKey);\r\n    } else {\r\n      if (node.left == null) return node.right;\r\n      if (node.right == null) return node.left;\r\n      Node pred = node.left;\r\n      while (pred.right != null) pred = pred.right;\r\n      node.info = pred.info;\r\n      node.left = deleteByType(node.left, pred.info.type);\r\n    }\r\n    return node;\r\n   }\r\n\r\n//Do not edit this function. Your task is to complete insert function above only.\r\n  void f1() throws Exception {\r\n    clear();\r\n    loadData(1);\r\n    String fname = \"f1.txt\";\r\n    File g123 = new File(fname);\r\n    if(g123.exists()) g123.delete();\r\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n    breadth(root,f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    inOrder(root,f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    f.close();\r\n   }  \r\n  \r\n//=============================================================\r\n void f2() throws Exception {\r\n    clear();\r\n    loadData(5);\r\n    String fname = \"f2.txt\";\r\n    File g123 = new File(fname);\r\n    if(g123.exists()) g123.delete();\r\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n    preOrder(root,f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    //------------------------------------------------------------------------------------\r\n    /*You must keep statements pre-given in this function.\r\n      Your task is to insert statements here, just after this comment,\r\n      to complete the question in the exam paper.*/\r\n    preOrder2(root, f);\r\n    //------------------------------------------------------------------------------------\r\n    f.writeBytes(\"\\r\\n\");\r\n    f.close();\r\n   }\r\n\r\n  void preOrder2(Node p, RandomAccessFile f) throws Exception {\r\n    if (p == null) return;\r\n    if (p.left != null || p.right != null) fvisit(p, f);\r\n    preOrder2(p.left, f);\r\n    preOrder2(p.right, f);\r\n   }\r\n\r\n//=============================================================\r\n  void f3() throws Exception {\r\n    clear();\r\n    loadData(9);\r\n    String fname = \"f3.txt\";\r\n    File g123 = new File(fname);\r\n    if(g123.exists()) g123.delete();\r\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n    breadth(root,f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    //------------------------------------------------------------------------------------\r\n    /*You must keep statements pre-given in this function.\r\n      Your task is to insert statements here, just after this comment,\r\n      to complete the question in the exam paper.*/\r\n    java.util.List<Node> inOrd = inOrderList(root);\r\n    if (inOrd.size() >= 4) {\r\n      Node p = inOrd.get(3);\r\n      root = deleteByType(root, p.info.type);\r\n    }\r\n    //------------------------------------------------------------------------------------\r\n    breadth(root,f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    f.close();\r\n   }\r\n\r\n//=============================================================\r\n void f4() throws Exception {\r\n    clear();\r\n    loadData(13);;\r\n    String fname = \"f4.txt\";\r\n    File g123 = new File(fname);\r\n    if(g123.exists()) g123.delete();\r\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n    breadth(root,f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    //------------------------------------------------------------------------------------\r\n    /*You must keep statements pre-given in this function.\r\n      Your task is to insert statements here, just after this comment,\r\n      to complete the question in the exam paper.*/\r\n    java.util.List<Node> pre = preOrderList(root);\r\n    int count = 0;\r\n    Node p = null;\r\n    for (Node node : pre) {\r\n      if (node.right != null) {\r\n        count++;\r\n        if (count == 3) { p = node; break; }\r\n      }\r\n    }\r\n    if (p != null && p.right != null) {\r\n      Brick tmp = p.info;\r\n      p.info = p.right.info;\r\n      p.right.info = tmp;\r\n    }\r\n    //------------------------------------------------------------------------------------\r\n    breadth(root,f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    f.close();\r\n   }\r\n\r\n }\r\n",
